<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Snake</title>
<style>
    body{
        margin:0;
        display:flex;
        flex-direction:column;
        align-items:center;
        justify-content:center;
        min-height:100vh;
        background:#111;
        color:#eee;
        font-family:sans-serif;
    }
    canvas{
        background:#222;
        display:block;
        margin:auto;
        border:2px solid #555;
    }
    #score{
        margin-top:10px;
        font-size:1.2em;
    }
    #controls{
        margin-top:10px;
    }
    button{
        margin:0 5px;
        padding:5px 12px;
        background:#333;
        color:#fff;
        border:none;
        border-radius:4px;
        cursor:pointer;
    }
    button:hover{
        background:#444;
    }
</style>
</head>
<body>
<canvas id="snake" width="400" height="400"></canvas>
<div id="score">Score: 0</div>
<div id="controls">
    <button id="start">Start</button>
    <button id="pause">Pause</button>
    <button id="reset">Reset</button>
</div>

<script>
(() => {
    const canvas = document.getElementById('snake');
    const ctx = canvas.getContext('2d');

    /* ----- configuration ----- */
    const CELL_COUNT = 20;          // board size (>=10)
    const w = CELL_COUNT;
    const h = CELL_COUNT;
    const cellSize = canvas.width / w;

    /* ----- game state ----- */
    let snake = [];                 // array of {x,y}, head first
    let dir = { x: 1, y: 0 };       // current direction
    let nextDir = { x: 1, y: 0 };   // queued direction
    let foodPos = { x: 0, y: 0 };
    let alive = true;
    let score = 0;
    let intervalId = null;

    /* ----- helpers ----- */
    function randFreeCell() {
        const free = [];
        for (let yy = 0; yy < h; yy++) {
            for (let xx = 0; xx < w; xx++) {
                if (!snake.some(p => p.x === xx && p.y === yy)) {
                    free.push({ x: xx, y: yy });
                }
            }
        }
        return free.length ? free[Math.floor(Math.random() * free.length)] : null;
    }

    function placeFood() {
        const pos = randFreeCell();
        if (pos) foodPos = pos;
        else foodPos = null; // board full – win condition (won’t happen normally)
    }

    function draw() {
        // background
        ctx.fillStyle = '#111';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // food
        if (foodPos) {
            ctx.fillStyle = '#0f0';
            ctx.fillRect(foodPos.x * cellSize, foodPos.y * cellSize, cellSize, cellSize);
        }

        // snake
        snake.forEach((segment, i) => {
            ctx.fillStyle = i === 0 ? '#ff0' : '#fff';
            ctx.fillRect(segment.x * cellSize, segment.y * cellSize, cellSize, cellSize);
        });

        // score
        document.getElementById('score').textContent = 'Score: ' + score;
    }

    function drawGameOver() {
        draw();
        ctx.fillStyle = 'rgba(0,0,0,0.6)';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = '#f00';
        ctx.font = '30px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2 + 10);
    }

    /* ----- public API ----- */
    window.game = {
        w,
        h,
        reset,
        tick,
        setDir,
        setFood,
        snake: () => snake.map(p => [p.x, p.y]),
        food: () => foodPos ? [foodPos.x, foodPos.y] : null,
        alive: () => alive,
        score: () => score,
    };

    function reset() {
        const cx = Math.floor(w / 2);
        const cy = Math.floor(h / 2);
        snake = [
            { x: cx + 1, y: cy },
            { x: cx,     y: cy },
            { x: cx - 1, y: cy }
        ];
        dir = { x: 1, y: 0 };
        nextDir = { x: 1, y: 0 };
        alive = true;
        score = 0;
        placeFood();
        draw();
    }

    function tick() {
        if (!alive) return;

        // apply queued direction (already validated in setDir)
        if (!(nextDir.x === -dir.x && nextDir.y === -dir.y)) {
            dir = nextDir;
        }

        const newHead = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

        // wall collision
        if (newHead.x < 0 || newHead.x >= w || newHead.y < 0 || newHead.y >= h) {
            alive = false;
            drawGameOver();
            return;
        }

        // self collision
        if (snake.some(p => p.x === newHead.x && p.y === newHead.y)) {
            alive = false;
            drawGameOver();
            return;
        }

        // move forward
        snake.unshift(newHead);

        // eat food?
        if (foodPos && newHead.x === foodPos.x && newHead.y === foodPos.y) {
            ++score;
            placeFood(); // grow (do not pop tail)
        } else {
            snake.pop(); // normal move
        }

        draw();
    }

    function setDir(direction) {
        const dirs = {
            up:    { x: 0, y: -1 },
            down:  { x: 0, y: 1 },
            left:  { x: -1, y: 0 },
            right: { x: 1, y: 0 }
        };
        const nd = dirs[direction];
        if (!nd) return;
        // ignore 180‑degree reversal
        if (nd.x === -dir.x && nd.y === -dir.y) return;
        nextDir = nd;
    }

    function setFood(x, y) {
        foodPos = { x: Number(x), y: Number(y) };
        draw();
    }

    /* ----- UI controls ----- */
    document.getElementById('start').addEventListener('click', () => {
        if (intervalId !== null) return;
        intervalId = setInterval(tick, 150);
    });

    document.getElementById('pause').addEventListener('click', () => {
        if (intervalId !== null) {
            clearInterval(intervalId);
            intervalId = null;
        }
    });

    document.getElementById('reset').addEventListener('click', () => {
        if (intervalId !== null) {
            clearInterval(intervalId);
            intervalId = null;
        }
        reset();
    });

    /* ----- keyboard ----- */
    window.addEventListener('keydown', e => {
        switch (e.key) {
            case 'ArrowUp':    setDir('up');    break;
            case 'ArrowDown':  setDir('down');  break;
            case 'ArrowLeft':  setDir('left');  break;
            case 'ArrowRight': setDir('right'); break;
        }
    });

    /* ----- initialise ----- */
    reset();
})();
</script>
</body>
</html>
